<script setup>
import {computed,onMounted,reactive,ref} from 'vue';import {accountApi} from '../../api/accountApi.js';import {money,date} from '../../api/client.js';import {useAuth} from '../../stores/auth.js';import {useToast} from '../../stores/toast.js';import BookingTicket from '../../components/BookingTicket.vue';import ProfileForm from '../../components/ProfileForm.vue';
const auth=useAuth(),toast=useToast(),tab=ref('bookings'),statusTab=ref('all'),bookings=ref([]),notifications=ref([]),ticket=ref(null),review=reactive({bookingId:null,rating:5,comment:''});
const filteredBookings=computed(()=>bookings.value.filter(b=>statusTab.value==='all'||(statusTab.value==='cancelled'?b.status==='CANCELLED':statusTab.value==='completed'?b.status==='PAID':statusTab.value==='upcoming'?['PAID','PENDING_PAYMENT'].includes(b.status):true)));
async function load(){try{[bookings.value,notifications.value]=await Promise.all([accountApi.bookings(),accountApi.notifications()])}catch(e){toast.show(e.message)}}async function saveProfile(data){try{const updated=await accountApi.updateProfile(data);auth.updateUser(updated);toast.show('Đã cập nhật hồ sơ')}catch(e){toast.show(e.message)}}async function cancel(code){if(!confirm('Bạn chắc chắn muốn hủy vé?'))return;try{await accountApi.cancel(code,'Khách hàng yêu cầu hủy');toast.show('Hủy vé thành công');load()}catch(e){toast.show(e.message)}}async function submitReview(){try{await accountApi.review(review.bookingId,{rating:review.rating,comment:review.comment});toast.show('Cảm ơn đánh giá của bạn');review.bookingId=null;review.comment=''}catch(e){toast.show(e.message)}}async function readNotification(id){try{await accountApi.readNotification(id);const item=notifications.value.find(n=>n.id===id);if(item)item.readFlag=true}catch(e){toast.show(e.message)}}function logout(){auth.logout();location.href='/'}onMounted(load);
</script>
<template><section class="section account-page figma-account"><aside class="account-menu"><h3>Tài khoản của tôi</h3><div class="profile-head"><span class="avatar large">{{auth.user.value?.fullName?.[0]}}</span><div><b>{{auth.user.value?.fullName}}</b><small>{{auth.user.value?.phone||auth.user.value?.email}}</small></div></div><button :class="{active:tab==='profile'}" @click="tab='profile'">♙ Thông tin cá nhân</button><button :class="{active:tab==='bookings'}" @click="tab='bookings'">▣ Lịch sử đặt vé</button><button :class="{active:tab==='notifications'}" @click="tab='notifications'">◉ Thông báo</button><button @click="tab='profile'">⌾ Đổi mật khẩu</button><button @click="logout">↪ Đăng xuất</button></aside><main class="account-content"><template v-if="tab==='bookings'"><h2>Lịch sử đặt vé</h2><div class="history-tabs"><button v-for="item in [{k:'all',n:'Tất cả'},{k:'upcoming',n:'Sắp đi'},{k:'completed',n:'Đã đi'},{k:'cancelled',n:'Đã hủy'}]" :key="item.k" :class="{active:statusTab===item.k}" @click="statusTab=item.k">{{item.n}}</button></div><BookingTicket v-for="booking in filteredBookings" :key="booking.code" :booking="booking" @cancel="cancel" @review="id=>review.bookingId=id" @view="ticket=booking"/><div v-if="!filteredBookings.length" class="empty card">Chưa có vé trong mục này.</div></template><ProfileForm v-else-if="tab==='profile'" :user="auth.user.value" @save="saveProfile"/><div v-else class="card profile-form"><h2>Thông báo</h2><button v-for="item in notifications" :key="item.id" class="notification-item" :class="{read:item.readFlag}" @click="readNotification(item.id)"><b>{{item.title}}</b><span>{{item.message}}</span></button><div v-if="!notifications.length" class="empty">Chưa có thông báo.</div></div></main><div v-if="ticket" class="modal ticket-modal" @click.self="ticket=null"><article class="electronic-ticket"><button class="modal-close" @click="ticket=null">×</button><h3>Vé điện tử</h3><div class="ticket-brand"><b>⚡ FastTravel</b><span>Đã thanh toán</span></div><small>Mã vé (Booking ID)</small><h2>{{ticket.code}}</h2><div class="ticket-qr">▦<small>Quét mã vé</small></div><dl><div><dt>Họ và tên</dt><dd>{{ticket.tickets?.[0]?.passengerName||auth.user.value?.fullName}}</dd></div><div><dt>Số điện thoại</dt><dd>{{auth.user.value?.phone}}</dd></div><div class="wide"><dt>Hành trình</dt><dd>{{ticket.trip.route}}</dd></div><div><dt>Thời gian</dt><dd>{{date(ticket.trip.departureTime)}}</dd></div><div><dt>Ghế</dt><dd>{{ticket.tickets?.map(t=>t.seat).join(', ')}}</dd></div></dl><div class="ticket-actions"><button onclick="window.print()">⇩ Tải vé (PDF)</button><a :href="'mailto:'+auth.user.value?.email+'?subject=Vé FastTravel '+ticket.code">✉ Gửi vé qua email</a></div></article></div><div v-if="review.bookingId" class="modal"><div class="card"><h3>Đánh giá chuyến đi</h3><select v-model.number="review.rating"><option v-for="x in [5,4,3,2,1]" :key="x" :value="x">{{'★'.repeat(x)}} ({{x}}/5)</option></select><textarea v-model="review.comment" placeholder="Chia sẻ trải nghiệm..."></textarea><button @click="review.bookingId=null">Đóng</button><button class="btn primary" @click="submitReview">Gửi đánh giá</button></div></div></section></template>
